def build_lora_projection(model, lora_rank=4):
    visual_projection = model.visual.head.proj    # Linear(in_features, out_features)
    text_projection = model.text.proj

    setattr(model.visual.head, "proj", lora_ft.Linear(model.visual.head.proj.in_features, model.visual.head.proj.out_features, lora_rank))
    for name, child in model.text.proj.named_children():
        if isinstance(child, nn.Linear):
            setattr(model.text.proj, name, lora_ft.Linear(child.in_features, child.out_features, lora_rank))

    lora_utils.mark_only_lora_as_trainable(model)

    return model
